import java.sql.*;

public class UserLookupServlet {
    // Look up a user by the username supplied in an HTTP request parameter
    public User findUser(Connection conn, String usernameFromRequest) throws SQLException {
        // Use a parameterized query: the SQL structure is fixed and the
        // user-supplied value is bound separately, never interpreted as SQL
        String sql = "SELECT id, username, email FROM users WHERE username = ?";

        // PreparedStatement with a bound parameter is the proper use of the JDBC API;
        // the driver handles escaping/typing so injection payloads are treated as plain data
        try (PreparedStatement pstmt = conn.prepareStatement(sql)) {
            pstmt.setString(1, usernameFromRequest); // bind the value safely

            try (ResultSet rs = pstmt.executeQuery()) {
                if (rs.next()) {
                    return new User(rs.getInt("id"), rs.getString("username"), rs.getString("email"));
                }
            }
        }
        return null;
    }
}
```

