            "name": "Smart Suggestion",
            "detail": "Contextual recommendation factoring in bill size, party size, service type, and local customs."
          },
          {
            "name": "Receipt Scan",
            "detail": "OCR-based scanning to instantly compute the tip and log the transaction."
          },
          {
            "name": "Traveler Mode",
            "detail": "Country and city-specific tipping etiquette guides for international users."
          },
          {
            "name": "Tip Trends",
            "detail": "Heatmaps and charts showing how tipping varies across neighborhoods, cuisines, and time."
          },
          {
            "name": "Server Insights (B2B)",
            "detail": "Anonymized dashboards for restaurant owners to understand how tipping at their venue compares to peers."
          }
        ],
        "privacy_and_trust": [
          "All tip submissions are anonymized and aggregated; no individual data is ever displayed.",
          "Minimum sample thresholds prevent identification of individual diners.",
          "Fraud detection flags outliers and suspicious submission patterns."
