        "initial_target": "Urban millennial and Gen Z diners in the top 10 U.S. metro areas, plus frequent business travelers.",
        "expansion": "International markets with evolving tipping cultures (Canada, UK, Australia, UAE) and adjacent service categories (rideshare, salons, delivery)."
      },
      "5_business_model": {
        "revenue_streams": [
          {
            "stream": "Freemium Consumer App",
            "detail": "Free core benchmarks; Tipperary Plus at $2.99/month unlocks trend analytics, unlimited receipt scans, and travel guides."
