        }
      },
      "6_competitive_landscape": {
        "existing_alternatives": [
          {
            "alternative": "Generic tip calculators",
            "weakness": "No venue-specific data; just arithmetic."
          },
          {
            "alternative": "Review platforms (Yelp, Google)",
            "weakness": "Cover food and service quality, not tipping behavior."
          },
          {
            "alternative": "POS default tip prompts (Toast, Square)",
            "weakness": "Set by the merchant, biased upward, and not comparable across venues."
          },
          {
            "alternative": "Etiquette blogs and articles",
            "weakness": "Static, generic, and quickly outdated."
          }
        ],
        "competitive_advantages": [
          "First-mover in building a proprietary, venue-level tipping dataset.",
          "Network effects: each contribution improves accuracy for all users.",
          "Neutral third-party positioning trusted by both diners and restaurants.",
